    // Where for node i: [bi, ci, di]^T = gradient of shape function N_i
    // The gradient of N_i is given by the i-th column of H_inv (not row), specifically
    // dN_i/dx = H_inv(1,i), dN_i/dy = H_inv(2,i), dN_i/dz = H_inv(3,i)
    // because H_inv * [1,x,y,z]^T gives the shape function values

    // Build B matrix (6x12)
    Eigen::Matrix<double, 6, 12> B = Eigen::Matrix<double, 6, 12>::Zero();
    for (int i = 0; i < 4; ++i) {
        int col_base = i * 3;
        // Get gradient of shape function N_i: [dN_i/dx, dN_i/dy, dN_i/dz]
        // These are H_inv(1,i), H_inv(2,i), H_inv(3,i) respectively
        double bi = H_inv(1, i);  // dN_i/dx
        double ci = H_inv(2, i);  // dN_i/dy
        double di = H_inv(3, i);  // dN_i/dz

        // Row 0: dN_i/dx for ux components
        B(0, col_base + 0) = bi;
        // Row 1: dN_i/dy for uy components
        B(1, col_base + 1) = ci;
        // Row 2: dN_i/dz for uz components
        B(2, col_base + 2) = di;
        // Row 3: dN_i/dy, dN_i/dx for exy = ∂u/∂y + ∂v/∂x
        B(3, col_base + 0) = ci;  // ∂u/∂y
        B(3, col_base + 1) = bi;  // ∂v/∂x
        // Row 4: dN_i/dz, dN_i/dy for eyz = ∂v/∂z + ∂w/∂y
        B(4, col_base + 1) = di;  // ∂v/∂z
        B(4, col_base + 2) = ci;  // ∂w/∂y
        // Row 5: dN_i/dz, dN_i/dx for ezx = ∂w/∂x + ∂u/∂z
        B(5, col_base + 0) = di;  // ∂w/∂x
        B(5, col_base + 2) = bi;  // ∂u/∂z
    }

    // Compute stiffness matrix: K = B^T * D * B * volume
    Eigen::Matrix<double, 12, 12> K_standard = B.transpose() * G * B * volume;

    // 🔥 FIX: Apply transpose to match NASTRAN assembly convention
    // As diagnosed: K[i,j] should be B[j]^T * D * B[i], but we computed B[i]^T * D * B[j]
    // So final K must be transposed to align with expected layout.
    K_standard.transposeInPlace();

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 12; ++i) {
        std::cout << "[";
        for (int j = 0; j < 12; ++j) {
            std::cout << std::scientific << std::setprecision(6) << K_standard(i, j);
            if (j < 11) std::cout << ",";
        }
        std::cout << "]";
        if (i < 11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}

